"""Ansible automation foundations, operations and Automation Controller."""
from ._catalog import build_guided_catalog

CATEGORIES = [
    {"id": "foundations", "title": "Inventory & Playbooks", "color": "sky", "blurb": "Hosts, YAML playbooks, modules, facts and execution flow."},
    {"id": "authoring", "title": "Roles, Variables & Reuse", "color": "mint", "blurb": "Roles, templates, handlers, collections and clean automation."},
    {"id": "safety", "title": "Secrets, Testing & Safe Changes", "color": "peach", "blurb": "Vault, check mode, idempotence, validation and rollout safety."},
    {"id": "controller", "title": "Ansible Tower / Automation Controller", "color": "lilac", "blurb": "Projects, inventories, credentials, job templates, workflows and RBAC."},
    {"id": "operations", "title": "Operations & Troubleshooting", "color": "rose", "blurb": "Execution environments, scale, failures, logs and recovery."},
]

TOPICS = build_guided_catalog([
    ("ansible-inventory", "Static & Dynamic Inventories", "foundations", "basic", "Inventory maps groups and hosts to connection details and variables. Dynamic inventory plugins query cloud or CMDB APIs so automation targets current infrastructure.", "[web]\napi-01 ansible_host=10.0.1.11\n[web:vars]\nansible_user=deploy", "When is a dynamic inventory useful?", "When hosts are created and removed frequently in a cloud or inventory system; it reduces stale hand-maintained host lists.", ["ansible-patterns"]),
    ("ansible-patterns", "Host Patterns & Target Selection", "foundations", "basic", "Patterns select hosts by name, group, intersection, exclusion or wildcard. Understand the effective target before running changes, especially with `--limit` and production inventories.", "ansible-playbook site.yml --limit 'web:&prod:!canary' --list-hosts", "What should you do before a production playbook run?", "Use `--list-hosts` with the same inventory, pattern and limit to inspect the exact target set before applying changes.", ["ansible-inventory", "ansible-check-mode"]),
    ("ansible-playbooks", "Playbooks, Plays & Tasks", "foundations", "basic", "A playbook contains plays that map hosts to ordered tasks. Plays define privilege escalation, variables, handlers and strategy; tasks call modules to declare the desired state.", "- hosts: web\n  become: true\n  tasks:\n    - name: Ensure nginx is installed\n      ansible.builtin.package: {name: nginx, state: present}", "What is the main purpose of a playbook?", "It describes repeatable desired state and the ordered tasks needed to apply that state to selected hosts.", ["ansible-modules", "ansible-idempotence"]),
    ("ansible-modules", "Modules, FQCNs & Module Return Values", "foundations", "basic", "Modules perform focused operations and return structured fields such as changed, failed, rc and stdout. Fully qualified collection names avoid ambiguity and make dependencies explicit.", "ansible.builtin.service: {name: nginx, state: started, enabled: true}", "Why prefer a module over a shell command when one exists?", "Modules model desired state, return structured results and are more reliably idempotent than shell commands that only report command execution.", ["ansible-playbooks", "ansible-idempotence"]),
    ("ansible-idempotence", "Idempotence & Change Reporting", "foundations", "basic", "An idempotent task converges to the desired state and reports no change on a second run. Use stateful modules, avoid unnecessary command/shell tasks and define `changed_when` only when command semantics are understood.", "Run the play twice: first run changed=1; second run changed=0", "Why is a play that always reports changed operationally harmful?", "It hides real drift, triggers unnecessary handlers and causes noisy runs; prefer modules that compare current state with the declared target.", ["ansible-modules", "ansible-check-mode"]),
    ("ansible-facts", "Facts, Setup & Fact Caching", "foundations", "intermediate", "Facts are host properties gathered by setup or returned by plugins. They enable platform-aware tasks; caching speeds large runs but needs freshness and access-control decisions.", "ansible.builtin.setup: filter=ansible_distribution*", "A play branches on an outdated OS fact. What might be responsible?", "A fact cache may be stale or gathering was disabled; inspect cache settings and refresh facts before relying on them for a critical change.", ["ansible-inventory", "ansible-conditionals"]),
    ("ansible-vars", "Variables, Scope & Precedence", "authoring", "intermediate", "Variables can come from inventory, group/host vars, play vars, role defaults/vars, extra vars and other sources with a defined precedence. Keep defaults low-precedence and avoid relying on obscure override chains.", "ansible-inventory -i inventory --host api-01 --yaml", "A value differs from group_vars; how do you trace the effective value?", "Inspect inventory and vars files, use `ansible-inventory --host`, review role defaults and vars, and check task/play vars and supplied extra vars.", ["ansible-inventory", "ansible-vault"]),
    ("ansible-conditionals", "When, Failed When & Changed When", "authoring", "intermediate", "Conditionals control task execution and custom result interpretation. `when` expressions are native YAML expressions; do not wrap them in Jinja braces, and ensure failure/change predicates match actual return codes.", "when: ansible_facts.os_family == 'Debian'", "Why is `when: '{{ flag }}'` discouraged?", "The `when` field already evaluates an expression; nested Jinja delimiters can produce strings or confusing behavior and modern Ansible warns against it.", ["ansible-facts", "ansible-loops"]),
    ("ansible-loops", "Loops, Loop Control & Registered Results", "authoring", "intermediate", "Loops apply one task across items; registered loop results contain a results list. Label output with `loop_control.label` and keep item data structured rather than constructing shell strings.", "loop: '{{ packages }}'\nloop_control:\n  label: '{{ item.name }}'", "A registered variable from a loop lacks the expected top-level `stdout`. Why?", "The task returns one result per item under `results`; inspect the nested structure and use a purpose-built module when aggregating state.", ["ansible-conditionals", "ansible-templates"]),
    ("ansible-handlers", "Handlers, Notify & Change-Driven Restart", "authoring", "intermediate", "A handler runs when notified by a changed task and normally runs once per play. This avoids restarting services when a configuration template is unchanged; `meta: flush_handlers` forces an earlier boundary.", "template: src=nginx.conf.j2 dest=/etc/nginx/nginx.conf\nnotify: restart nginx", "Why did a service handler not run?", "The notifying task may not have changed, the handler name may not match, or a later task failed before handlers ran; inspect the result and handler notifications.", ["ansible-idempotence", "ansible-templates"]),
    ("ansible-templates", "Jinja Templates & Safe Configuration Rendering", "authoring", "intermediate", "The template module renders Jinja into a managed file and can validate it with the target application's syntax checker before replacing the file. Keep secrets out of rendered output and quote types deliberately.", "template: src=app.conf.j2 dest=/etc/app/app.conf validate='app --check-config %s'", "How can a template update avoid installing invalid service configuration?", "Use the template module's `validate` command to check a temporary rendered file before it replaces the destination, then notify a controlled reload handler.", ["ansible-handlers", "ansible-vault"]),
    ("ansible-roles", "Roles: Defaults, Tasks, Handlers & Files", "authoring", "basic", "Roles package related defaults, vars, tasks, handlers, templates and files behind a reusable interface. Put overrideable values in defaults and document required variables and supported platforms.", "roles/nginx/{defaults,tasks,handlers,templates,files}/", "What belongs in role defaults rather than role vars?", "Overrideable settings belong in defaults because they have lower precedence; role vars are intended for values that should be harder to override.", ["ansible-playbooks", "ansible-collections"]),
    ("ansible-role-deps", "Role Dependencies & Galaxy Requirements", "authoring", "intermediate", "Galaxy requirements pin role and collection sources and versions so automation environments can be reproduced. Treat dependencies as supply-chain inputs and review checksums, publishers and update policy.", "ansible-galaxy install -r requirements.yml", "Why pin collection and role versions in CI?", "It prevents an unreviewed upstream release from changing playbook behavior between runs and makes the execution environment reproducible.", ["ansible-collections", "ansible-execution-env"]),
    ("ansible-collections", "Collections & Namespaced Automation", "authoring", "intermediate", "Collections package modules, plugins, roles and documentation under a namespace. Declare collections in requirements and use FQCNs so runtime dependencies and module ownership are visible.", "collections:\n  - name: community.general\n    version: 10.0.0", "A module works on one laptop but not in the execution environment. What do you check?", "Verify the collection is installed in the same runtime, the FQCN and version are correct, and the target execution environment includes the dependency.", ["ansible-modules", "ansible-execution-env"]),
    ("ansible-import-include", "Static Import vs Dynamic Include", "authoring", "advanced", "Imports are processed statically during parsing; includes are evaluated dynamically at runtime. Choose based on conditional task selection, tag behavior, loops and readability rather than habit.", "import_tasks: hardening.yml · include_tasks: '{{ os_family }}.yml'", "Why might a tag on include_tasks not run included tasks?", "Dynamic includes do not automatically propagate every tag to their children; use `apply` or tag the included tasks as required.", ["ansible-roles", "ansible-conditionals"]),
    ("ansible-delegation", "Delegation, Local Actions & Run Once", "authoring", "advanced", "Delegation runs a task on another host, while `run_once` executes once for a play batch. These controls are useful for load balancers and orchestration but can create races under parallel strategy.", "delegate_to: localhost · run_once: true · serial: 10%", "A database migration runs twice during a rolling deployment. What could be wrong?", "The migration task is executing once per target or batch; delegate it appropriately, use run_once with a controlled strategy, and make the migration itself safe to retry.", ["ansible-strategy", "ansible-rolling"]),
    ("ansible-blocks", "Blocks, Rescue & Always Cleanup", "safety", "intermediate", "Blocks group tasks under shared conditions and privilege; rescue handles task failures and always performs cleanup. A rescued failure changes play behavior, so report the recovery and preserve failure visibility.", "block: deploy\nrescue: rollback\nalways: remove temporary files", "Why should a rescue section not simply swallow every failure?", "A play can appear successful while the system remains unhealthy; verify recovery, fail explicitly if needed and retain diagnostics for operators.", ["ansible-errors", "ansible-rolling"]),
    ("ansible-check-mode", "Check Mode, Diff Mode & Limitations", "safety", "intermediate", "Check mode estimates changes without applying them when modules support it; diff mode shows file changes and may expose secrets. Some command tasks and dependencies cannot be predicted accurately.", "ansible-playbook site.yml --check --diff --limit web", "Does a clean check-mode run prove a playbook will succeed?", "No. Modules may not support check mode, runtime dependencies can differ, and later tasks may depend on changes that were only predicted.", ["ansible-idempotence", "ansible-secrets"]),
    ("ansible-secrets", "Ansible Vault & Secret Handling", "safety", "intermediate", "Vault encrypts files or variables at rest; execution still decrypts values into process memory and possibly logs or target files. Use managed secret stores and `no_log` selectively for sensitive tasks.", "ansible-vault encrypt group_vars/prod/vault.yml", "Why is Vault alone not enough to protect a password?", "The secret can leak through task output, debug, rendered files or controller logs after decryption; control access, minimize exposure and rotate credentials.", ["ansible-vault-ids", "ansible-templates"]),
    ("ansible-vault-ids", "Vault IDs, Password Sources & Rotation", "safety", "advanced", "Vault IDs distinguish encryption keys across environments and password sources should come from protected files or secret managers, not shell history. Rotation requires re-encrypting data and coordinating consumers.", "--vault-id prod@script:/secure/get-prod-vault-pass", "How should a team rotate a Vault password without breaking production runs?", "Plan encrypted-variable rekeying, update protected controller credentials and CI secret sources, verify access in a non-production run, then retire the old key.", ["ansible-secrets", "controller-credentials"]),
    ("ansible-no-log", "no_log, Debugging & Sensitive Output", "safety", "intermediate", "`no_log: true` suppresses task arguments and results from output, which can protect secrets but also removes troubleshooting evidence. Apply it only to sensitive tasks and emit safe status metadata separately.", "no_log: true on secret-bearing API task; log request ID and outcome only", "A secret is hidden but operators cannot diagnose an API failure. What is a safe pattern?", "Keep secret-bearing arguments masked, capture a request ID and status code without payloads, and use restricted target/controller logs for detailed diagnostics.", ["ansible-secrets", "controller-job-output"]),
    ("ansible-tags", "Tags, Skip Tags & Operational Slices", "safety", "intermediate", "Tags select subsets of tasks for targeted operations, while `always` and `never` change normal tag behavior. Tagging creates an operator interface that must preserve prerequisite tasks.", "ansible-playbook site.yml --tags patch --list-tasks", "Why can running a tag directly skip required preparation?", "Tag filtering can omit dependencies and setup tasks; inspect the selected task list and define tag inheritance and prerequisites deliberately.", ["ansible-playbooks", "ansible-check-mode"]),
    ("ansible-rolling", "Serial, Batch Size & Rolling Deployment Safety", "safety", "advanced", "`serial` controls how many hosts a play updates at once; `max_fail_percentage` and health checks bound blast radius. Drain traffic before changes and verify service health before continuing batches.", "serial: 10% · max_fail_percentage: 0 · verify health before next batch", "How does serial reduce deployment risk?", "It limits the number of hosts changed concurrently, allowing health validation and a stop before the full fleet is affected.", ["ansible-strategy", "ansible-delegation"]),
    ("ansible-strategy", "Linear, Free & Host Execution Strategies", "safety", "advanced", "The linear strategy completes each task across a batch before moving on; free lets hosts advance independently. Strategy, forks, serial and delegation interact to affect ordering and concurrency.", "strategy: linear · forks: 20 · serial: 5", "A task assumes every host completed the previous task, but failures appear intermittently. Which setting matters?", "A free strategy allows hosts to advance independently; use linear where cross-host task ordering is required and add explicit coordination for shared operations.", ["ansible-rolling", "ansible-delegation"]),
    ("ansible-errors", "Retries, Until & Failure Semantics", "safety", "intermediate", "`until` retries a task until a condition succeeds, with `retries` and `delay` bounding the wait. Retry only transient operations; make side effects idempotent and distinguish unavailable dependencies from invalid configuration.", "until: result.status == 200 · retries: 6 · delay: 5", "Why should a task not retry an invalid configuration error for several minutes?", "It cannot become valid by waiting and only delays diagnosis; classify errors and retry only conditions that can recover transiently.", ["ansible-blocks", "ansible-idempotence"]),
    ("ansible-assert", "Assertions, Preconditions & Postconditions", "safety", "intermediate", "Assertions make assumptions explicit before changing systems and verify outcomes after tasks. Fail early with a clear message when required variables, versions, capacity or health conditions are absent.", "assert: that: [app_version is defined, replicas | int >= 2]", "What is a useful precondition before a database migration?", "Assert target environment, backup status, expected schema version, maintenance window and a valid migration artifact before executing changes.", ["ansible-check-mode", "ansible-rolling"]),
    ("ansible-validate", "ansible-lint, Syntax Check & YAML Validation", "safety", "basic", "Use ansible-lint and syntax checks to catch style, deprecated modules and structural errors; add inventory parsing and playbook tests in CI. Pin tool versions to keep feedback repeatable.", "ansible-lint && ansible-playbook -i inventory site.yml --syntax-check", "What does syntax-check not validate?", "It does not prove target connectivity, module behavior, variable values, permissions or successful runtime convergence; run tests in a controlled environment too.", ["ansible-molecule", "ansible-idempotence"]),
    ("ansible-molecule", "Molecule: Test Roles in Disposable Environments", "safety", "intermediate", "Molecule creates test instances, converges a role, verifies state and can test idempotence and cleanup. Choose drivers that reflect supported platforms and keep test fixtures deterministic.", "molecule test → create → converge → verify → idempotence → destroy", "How does an idempotence test reveal a role defect?", "It runs convergence again and checks that no unexpected changes occur, revealing templates, commands or services that continually drift.", ["ansible-roles", "ansible-validate"]),
    ("ansible-check-hosts", "Connection Plugins, SSH & Become", "foundations", "intermediate", "Connection plugins control how Ansible reaches hosts; privilege escalation controls remote identity. Configure SSH keys, host key verification, Python paths and become policy explicitly.", "ansible_user=deploy · become=true · become_method=sudo", "A task connects but package installation is denied. Which boundary is missing?", "The remote user may lack privilege escalation or sudo policy; verify become settings and permitted commands without embedding a shared root password.", ["ansible-inventory", "controller-credentials"]),
    ("ansible-forks", "Forks, Async Tasks & Polling", "operations", "intermediate", "Forks set parallel host execution; async/poll allows long-running tasks to continue while Ansible checks completion. Tune concurrency against control-node capacity and target service limits.", "async: 1800 · poll: 15 · forks: 20", "Why can increasing forks make an outage worse?", "It can overwhelm a control node, API, network or target fleet and multiply simultaneous changes; increase gradually with limits and health checks.", ["ansible-strategy", "ansible-rolling"]),
    ("ansible-callbacks", "Callback Plugins & Structured Job Output", "operations", "intermediate", "Callback plugins format task output, aggregate timing or emit structured events. Controller job output should support audit and troubleshooting while respecting secret masking and retention controls.", "Enable an approved callback for JSON event output in a controlled run", "Why is task-level structured output useful for automation operations?", "It supports audit, trend analysis and targeted diagnosis without parsing a long human-formatted console transcript.", ["controller-job-output", "ansible-no-log"]),
    ("ansible-debugging", "Debug with Verbosity, Tags & Targeted Runs", "operations", "basic", "Use inventory inspection, `--list-hosts`, tags, limits and moderate verbosity to narrow a failure. Higher verbosity can expose sensitive details, so capture and share logs carefully.", "ansible-playbook site.yml --limit api-01 --tags config -vv", "A playbook fails on one host in a 500-host inventory. How do you reproduce safely?", "Limit to the failing host and relevant tags in a safe environment, inspect variables and task output, and avoid rerunning fleet-wide changes just to gather diagnostics.", ["ansible-patterns", "ansible-no-log"]),
    ("ansible-pipelining", "SSH Pipelining, ControlPersist & Performance", "operations", "advanced", "SSH connection reuse and pipelining can reduce setup overhead. They must align with sudo requiretty, Python discovery, SSH multiplexing and security policies; measure before changing broad fleet defaults.", "ControlMaster auto · ControlPersist 60s · pipelining enabled where compatible", "A pipelining change breaks privilege escalation on legacy hosts. What do you inspect?", "Check sudo requiretty settings, connection plugin options and per-host compatibility, then scope the optimization to supported groups.", ["ansible-check-hosts", "ansible-forks"]),
    ("ansible-fact-cache", "Fact Cache Backends & Freshness", "operations", "advanced", "Fact cache backends reduce repeated gathering in large inventories but cached data can become stale or cross environment boundaries. Scope cache keys, permissions and expiry to host identity and expected freshness.", "Use a namespaced Redis cache with a short TTL for dynamic cloud facts", "When can fact caching make a playbook less safe?", "When stale facts drive destructive conditionals or host selection; define TTLs, refresh critical facts and isolate environments.", ["ansible-facts", "ansible-inventory"]),
    ("ansible-dynamic-inventory", "Cloud Dynamic Inventory Plugins", "foundations", "intermediate", "Cloud inventory plugins query APIs and compose groups from tags, regions or project metadata. Credentials, API throttling, caching and group naming determine whether inventory is reliable and least-privileged.", "plugin: amazon.aws.aws_ec2\nregions: [us-east-1]\nkeyed_groups: [{key: tags.Environment}]", "The cloud inventory returns no hosts although instances exist. What do you check?", "Verify plugin collection version, credentials and API permissions, selected accounts/regions, filters, cache freshness and the generated inventory output.", ["ansible-inventory", "ansible-patterns"]),
    ("ansible-windows", "Windows Hosts, WinRM & Windows Modules", "foundations", "intermediate", "Windows automation uses Windows connection settings such as WinRM or PSRP and Windows-specific modules. Certificate validation, transport security, credentials and PowerShell version must be configured deliberately.", "ansible_connection: psrp · ansible_winrm_transport: kerberos", "A Linux playbook works but Windows targets fail before tasks start. What should you review?", "Check the Windows connection plugin, WinRM/PSRP listener and firewall, authentication transport, certificate validation and required collection/module support.", ["ansible-inventory", "ansible-check-hosts"]),
    ("ansible-network", "Network Automation & Network Collections", "foundations", "advanced", "Network collections use platform-specific modules and often connect over network APIs or CLI rather than a remote Python interpreter. Use structured configuration resources and validate candidate changes before commit.", "Use vendor collection modules to render, diff and commit a router interface change", "Why is `ansible.builtin.command` often the wrong tool for network configuration?", "Network devices may not provide a general shell; platform modules understand configuration state, produce diffs and support device-specific transport.", ["ansible-collections", "ansible-check-mode"]),
    ("ansible-filters", "Jinja Filters, Tests & Data Shaping", "authoring", "intermediate", "Filters transform values and tests classify them in expressions. Keep data shaping readable, avoid unsafe dynamic evaluation and validate types at boundaries before rendering configurations.", "{{ packages | selectattr('enabled') | map(attribute='name') | list }}", "A Jinja expression unexpectedly treats `false` as true. What should you check?", "Inspect whether the value is a string such as 'false' rather than a Boolean, normalize input types and use explicit tests or conversion filters.", ["ansible-vars", "ansible-templates"]),
    ("ansible-lookups", "Lookup & Query Plugins", "authoring", "intermediate", "Lookup plugins retrieve data from controller-side files, environment, secret managers or APIs; query filters operate on structured collections. Know whether code runs locally or on the managed host.", "lookup('ansible.builtin.env', 'DEPLOY_ENV')", "A lookup cannot read a file that exists only on the target host. Why?", "Lookups execute on the controller; use a remote module such as `slurp` or `fetch` when data must be read from a managed host.", ["ansible-vars", "ansible-secrets"]),
    ("ansible-async", "Long-Running Jobs & Async Status", "operations", "advanced", "Async tasks return job identifiers that can be polled later, allowing long-running work to continue without holding a connection. Define timeouts and cleanup and ensure retries do not duplicate side effects.", "async: 3600 · poll: 0 → async_status jid until finished", "What risk comes with fire-and-forget `poll: 0`?", "The controller does not wait for completion, so failures may go unnoticed; explicitly poll, collect status and clean up job cache files.", ["ansible-forks", "ansible-errors"]),
    ("ansible-diff-review", "Review Diffs Before Applying Changes", "safety", "intermediate", "Diff output shows proposed file changes and can be reviewed with check mode; it is strongest for templates and configuration modules that support it. Treat diffs as sensitive if they include rendered secrets.", "--check --diff with `no_log` or secret-safe template design", "A diff contains a newly rendered credential. What needs to change?", "Avoid rendering long-lived secrets into broadly visible files or job output, use target-side secret references, and restrict or mask sensitive task output.", ["ansible-check-mode", "ansible-no-log"]),
    ("ansible-rolling-restart", "Drain, Update & Rejoin Hosts Safely", "safety", "advanced", "A safe rolling restart drains a host from traffic, waits for active work, updates and checks service health, then rejoins it before the next host. Delegated load balancer calls need explicit failure recovery.", "delegate drain → update one host → verify health → delegate rejoin", "A host stays drained after an automation failure. What design prevents this?", "Use block/rescue/always cleanup, track drain state, make rejoin idempotent and alert when a target remains out of service.", ["ansible-rolling", "ansible-blocks"]),
    ("controller-overview", "Ansible Tower, AWX & Automation Controller", "controller", "basic", "AWX is the upstream automation platform; Red Hat Ansible Automation Platform includes Automation Controller, historically called Tower. Controller provides a web/API control plane for governed job execution.", "Git project + inventory + credential + job template → execution environment", "What does Tower/Automation Controller add beyond running `ansible-playbook` locally?", "Centralized inventory and credential management, RBAC, job templates, schedules, workflows, audit records and consistent execution environments.", ["controller-projects", "controller-rbac"]),
    ("controller-projects", "Controller Projects & SCM Updates", "controller", "intermediate", "A project synchronizes playbooks and roles from a source repository at a revision. Pin branches or immutable commits appropriately, control update-on-launch behavior and ensure credential scope is read-only where possible.", "Project URL → signed SCM credential → reviewed branch or commit → sync", "A job used an old playbook after a commit. What do you inspect?", "Check project revision and last sync, update-on-launch setting, SCM credential and branch/ref, then confirm the job template uses that project.", ["controller-overview", "controller-templates"]),
    ("controller-inventories", "Controller Inventories, Sources & Groups", "controller", "intermediate", "Controller inventories hold hosts/groups and can synchronize from cloud or external sources. Credentials and source filters govern discovery; inventory variables should not become a secret store.", "Inventory source: cloud account → region and tag filters → synchronized groups", "A job template reports zero hosts after inventory sync. How do you debug it?", "Inspect source sync output, credentials, filters, organization/project association, limit pattern and inventory group membership.", ["controller-overview", "ansible-dynamic-inventory"]),
    ("controller-credentials", "Controller Credentials & Secret Injection", "controller", "intermediate", "Credentials store machine, SCM, vault, cloud and API secrets and inject them into jobs. Scope credential use to teams/templates, rotate centrally and prefer short-lived cloud identity when supported.", "Machine credential + Vault credential + cloud credential attached to a job template", "Why should operators avoid pasting SSH keys into playbook variables?", "They may be exposed in source, logs or exported artifacts; Controller credentials centralize encryption, masking, access control and rotation.", ["controller-rbac", "ansible-secrets"]),
    ("controller-rbac", "Controller Organizations, Teams & RBAC", "controller", "intermediate", "Controller RBAC grants roles on organizations, projects, inventories, credentials and job templates. Separate who can edit automation from who can launch it and who can use sensitive credentials.", "Platform team administers inventory; app team may launch approved template only", "A user can launch a job but should not reveal its cloud credential. Which boundary matters?", "Grant execute on the approved job template without read/use access that exposes the credential; test effective roles through the user's account.", ["controller-credentials", "controller-templates"]),
    ("controller-templates", "Job Templates, Surveys & Limits", "controller", "basic", "Job templates define the project, inventory, playbook, credentials, execution environment and launch options. Surveys collect validated inputs; limits and forks should have safe defaults and narrow bounds.", "Template: patch-web · inventory=prod-web · limit required · survey change_ticket", "Why are surveys safer than letting users pass arbitrary extra variables?", "A survey constrains input names and choices and makes launch intent visible; arbitrary extra vars can override critical safeguards and target unintended resources.", ["controller-rbac", "controller-inventories"]),
    ("controller-workflows", "Workflow Job Templates & Approval Nodes", "controller", "intermediate", "Workflow templates connect jobs with success, failure or always paths, approvals and notifications. Model dependency order explicitly, pass only needed artifacts and preserve rollback/compensation paths.", "Validate → approval → deploy canary → health check → promote or rollback", "How do you ensure production deploy waits for approval?", "Place an approval node on the success path before the production deployment node and grant approval rights to the intended group only.", ["controller-templates", "controller-notifications"]),
    ("controller-schedules", "Schedules, Time Zones & Survey Defaults", "controller", "intermediate", "Schedules launch templates at defined times and may repeat based on cron-like rules. Time zones, daylight changes, inventory freshness and overlapping jobs must be handled deliberately.", "Nightly compliance scan at 02:00 UTC with concurrency policy", "A scheduled job ran twice during a daylight-saving transition. What should be reviewed?", "Inspect the configured time zone and schedule semantics, then choose a stable zone such as UTC and prevent overlapping duplicate executions.", ["controller-templates", "controller-workflows"]),
    ("controller-notifications", "Controller Notifications & Event Destinations", "controller", "intermediate", "Notifications report job and workflow outcomes to approved destinations. Templates should include job ID, inventory, revision and safe error context without leaking credentials or full sensitive stdout.", "Failure notification → owning team → job URL + revision + sanitized summary", "What should a failure notification include for useful triage?", "A link to the job, template, inventory, revision, failed task summary and owner, with secret values and sensitive payloads masked.", ["controller-workflows", "controller-job-output"]),
    ("controller-job-output", "Job Events, Output & Audit Trail", "controller", "intermediate", "Controller records job events, status and output for audit and troubleshooting. Retention, access and export policies should match operational needs and protect sensitive values.", "Filter events by failed host/task and correlate job ID with change ticket", "Why keep job events instead of only the final stdout?", "Structured events identify task, host, timing and change status, enabling precise triage and audit without parsing an unstructured transcript.", ["controller-notifications", "ansible-callbacks"]),
    ("controller-execution-env", "Execution Environments & Reproducible Runtime", "controller", "intermediate", "Execution environments are container images that package Ansible, collections, Python dependencies and system tools. Pin and scan images, rebuild from reviewed definitions and test controller compatibility.", "ansible-builder build → scan → push immutable image digest → assign to template", "A playbook succeeds locally but fails in Controller because a collection is missing. What solves the mismatch?", "Package the Ansible version, collections and dependencies into the execution environment and attach that tested image to the job template.", ["ansible-execution-env", "controller-templates"]),
    ("controller-instance-groups", "Instance Groups, Capacity & Isolation", "controller", "advanced", "Instance groups control where jobs run and can separate execution by network, credential sensitivity or workload. Capacity, forks and job slicing affect queue time and target load.", "Route restricted production jobs to isolated execution nodes with bounded capacity", "Why might a private-network inventory need a dedicated instance group?", "Only execution nodes in that group may reach the private hosts, limiting network exposure and separating workload capacity and trust boundaries.", ["controller-execution-env", "ansible-forks"]),
    ("controller-job-slicing", "Job Slicing & Large Inventory Runs", "controller", "advanced", "Job slicing divides a large inventory across parallel jobs to reduce runtime. It changes failure and aggregation behavior; ensure tasks are host-independent or coordinate shared operations.", "Slice a read-only compliance scan across inventory partitions", "Why is job slicing risky for a one-time database migration?", "Multiple slices may run the shared migration concurrently. Use coordination or a single dedicated step for shared side effects.", ["controller-instance-groups", "ansible-delegation"]),
    ("controller-api", "Controller REST API & Workflow Automation", "controller", "advanced", "The Controller API can launch approved templates, query job state and integrate with portals. Use scoped tokens, TLS, idempotent clients, pagination and audit; never expose a broad token in frontend code.", "POST approved job template launch → poll job status → record job ID", "What is a safe pattern for launching Controller jobs from an internal portal?", "Authenticate server-side with a narrowly scoped service identity, allow-list templates and validated survey inputs, then record job IDs and audit context.", ["controller-rbac", "controller-templates"]),
    ("controller-webhooks", "SCM Webhooks & Event-Driven Automation", "controller", "advanced", "SCM webhooks can launch automation when a repository event matches a configured rule. Validate event source and branch, authenticate webhook delivery and constrain the template and inventory it can reach.", "Reviewed merge to main → webhook rule → non-production validation job", "Why should a webhook not launch a production template from any branch?", "An untrusted branch or forged event could execute unreviewed automation; verify signatures, repository, branch and approval path and limit credentials.", ["controller-projects", "controller-workflows"]),
    ("controller-approvals", "Approval Policies & Separation of Duties", "controller", "advanced", "Approval nodes and RBAC separate authorship, execution and production approval. Audit who approved which revision and ensure a requester cannot silently approve their own high-risk change where policy requires separation.", "Change request → peer approval → production workflow node → audited result", "What evidence should an approval decision capture?", "The exact project revision, target inventory/environment, change ticket, reviewer identity, time and any verification evidence needed to reconstruct the decision.", ["controller-workflows", "controller-rbac"]),
    ("controller-troubleshooting", "Troubleshoot Controller Job Failures", "operations", "intermediate", "Separate queue/scheduling issues, project sync failures, credential errors, execution-environment problems, inventory selection and task failures. Job events and node logs narrow the failing layer.", "Check job status/detail → event stream → project sync → credential and execution node", "A job remains pending rather than failing a task. Where do you start?", "Inspect capacity and instance-group availability, job slicing, dependency jobs, schedule/approval state and controller queue before debugging playbook code.", ["controller-instance-groups", "controller-job-output"]),
    ("ansible-roles-api", "Role Interface Design & Documentation", "authoring", "intermediate", "A reusable role should document supported operating systems, required variables, defaults, side effects, handlers and verification. Stable interfaces reduce hidden coupling between teams.", "README: purpose · inputs · supported platforms · example · tests", "What belongs in a role's public interface?", "Only the variables, tags and behaviors callers need to rely on; document required inputs and avoid exposing internal implementation details as contracts.", ["ansible-roles", "ansible-molecule"]),
    ("ansible-collections-publish", "Build & Publish an Ansible Collection", "authoring", "advanced", "Collection builds package plugins and docs with a versioned manifest. Validate content, dependencies and signatures, then publish to an approved Galaxy or private automation hub repository.", "ansible-galaxy collection build && ansible-galaxy collection publish artifact.tar.gz", "What should CI validate before publishing a collection?", "Lint and syntax, documentation, integration tests, dependency pins, version metadata, license and release provenance before an immutable version is published.", ["ansible-collections", "ansible-validate"]),
    ("ansible-drift", "Drift Detection & Scheduled Convergence", "operations", "intermediate", "Scheduled check-mode or read-only compliance runs detect configuration drift; convergence runs restore desired state. Alert on unexpected changes and coordinate automation with change windows and human operations.", "Nightly audit → report changed tasks → approved remediation workflow", "Why separate drift detection from automatic remediation for some systems?", "Some changes may be intentional, regulated or unsafe to revert automatically; report and classify drift before applying corrective changes.", ["controller-schedules", "ansible-check-mode"]),
    ("ansible-api-rate", "Rate Limits & External API Hygiene", "operations", "advanced", "Automation that calls cloud, CMDB or ticket APIs must handle pagination, throttling, retries, timeouts and partial failure. Use least-privileged credentials and avoid retrying non-idempotent operations blindly.", "Bound API concurrency; retry 429 with backoff and request ID logging", "A dynamic inventory plugin intermittently returns incomplete data under scale. What do you investigate?", "Check API rate limits, pagination, timeouts, plugin cache, partial response handling and concurrency; capture request IDs and retry with bounded backoff.", ["ansible-dynamic-inventory", "ansible-errors"]),
    ("ansible-upgrade", "Upgrade Ansible Core & Collection Compatibility", "operations", "advanced", "Ansible core and collection versions evolve independently. Pin supported combinations in the execution environment, read porting guides, test deprecated behavior and upgrade in a canary environment first.", "Build candidate EE → run lint and Molecule matrix → canary Controller template", "Why might a collection upgrade break an unchanged playbook?", "A module interface, default, dependency or minimum core version may have changed; pin and test compatible versions before promoting the execution image.", ["ansible-execution-env", "ansible-role-deps"]),
    ("ansible-deprecations", "Deprecations, Warnings & Porting Guides", "operations", "intermediate", "Deprecation warnings provide a migration window before behavior is removed. Treat warnings as backlog items, enable targeted warning output in CI and consult the version-specific porting guide.", "Capture deprecation warnings on a pinned core version and migrate to FQCN/new parameter", "Why should a team not ignore deprecation warnings until an upgrade fails?", "Warnings can become errors or change behavior in a major release; early migration makes changes smaller and easier to test.", ["ansible-upgrade", "ansible-validate"]),
    ("controller-credential-types", "Custom Credential Types & Injectors", "controller", "advanced", "Custom credential types define validated inputs and inject them into environment variables or files for job execution. Restrict who can create and attach them because injection controls access to secrets and runtime.", "Define schema fields → inject short-lived token into approved environment variable", "What is the risk of allowing all users to create credential types?", "A custom injector can expose secrets or alter runtime behavior; limit management rights, review schemas and test masking and scope.", ["controller-credentials", "controller-rbac"]),
    ("controller-logs", "Controller Capacity, Logs & Service Health", "operations", "advanced", "Controller services, database, message broker and execution nodes all affect job availability. Monitor queue depth, callback processing, disk, database health and node capacity and follow supported recovery procedures.", "Track queued jobs, execution utilization, database connectivity and log volume", "Jobs fail across many unrelated templates at once. What points toward a platform issue?", "A broad correlated failure suggests controller, database, broker, credential backend or execution infrastructure; inspect platform health before changing individual playbooks.", ["controller-troubleshooting", "controller-instance-groups"]),
], "ANS", "Automation should be predictable, reviewable and safe to rerun; Controller adds shared governance without changing the need for good playbooks.")

